export class TaskRepository {
  private store = new Map<string, any>();

  async save(task: any): Promise<string> {
    const id = task.id || `task-${this.store.size + 1}`;
    this.store.set(id, { ...task, id });
    return id;
  }

  async find(id: string) {
    return this.store.get(id) || null;
  }

  async delete(id: string): Promise<boolean> {
    return this.store.delete(id);
  }
}

--- taskService.ts ---
import { TaskRepository } from './taskRepository';

export class TaskService {
  constructor(private repo: TaskRepository) {}

  async createTask(title: string): Promise<{ id: string }> {
    if (!title || title.trim().length === 0) {
      throw new Error('Task title is required');
    }
    const id = await this.repo.save({ title, done: false });
    return { id };
  }

  async getTask(id: string) {
    const task = await this.repo.find(id);
    if (!task) {
      throw new Error(`Task ${id} not found`);
    }
    return task;
  }

  async completeTask(id: string) {
    const task = await this.getTask(id);
    task.done = true;
    await this.repo.save(task);
    return task;
  }
}

